contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(to != address(0));
        // acquire tokens via the airdrop (fresh contract: sender not blacklisted)
        c.getTokens();
        uint256 senderBalBefore = c.balanceOf(address(this));
        require(amount <= senderBalBefore);
        uint256 toBalBefore = c.balanceOf(to);

        bool ok = c.transfer(to, amount);

        assert(ok && c.balanceOf(address(this)) == senderBalBefore - amount && c.balanceOf(to) == toBalBefore + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 amount) public {
        require(spender != address(0));
        require(amount > 0);
        // acquire tokens via the airdrop (fresh contract: sender not blacklisted)
        c.getTokens();
        require(amount <= c.balanceOf(address(this)));

        bool okApprove = c.approve(spender, amount);
        require(okApprove);

        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(spender);
        uint256 allowanceBefore = c.allowance(address(this), spender);

        bool ok = c.transferFrom(address(this), spender, amount);

        assert(ok
            && c.balanceOf(address(this)) == fromBefore - amount
            && c.balanceOf(spender) == toBefore + amount
            && c.allowance(address(this), spender) == allowanceBefore - amount);
    }

    receive() external payable {}
}

